"""The red-line corpus (JV-13): every draft the guard must get right.

tests/test_redlines.py reads it. Each outbound case is a text MIYA might
propose to a client with the verdict the deterministic guard
(miya/jarvis/redlines.py) must give it: ``block`` with the flags that must
be among the ones reported, or ``ok``. Each inbound case is a client message
with the signals ``classify_inbound`` must find (``quiet`` — none at all).

A false pass of a promise or a price is the worst failure the guard can
make; a false block only costs the owner an escalation. So every doubtful
phrasing is a ``block`` case, and ``ok`` holds only greetings, questions
that gather details, deferrals and plain facts.

Uzbek cases are written in Latin; the tests also run every one of them
transliterated to Cyrillic (``text.transliterate``), which is how the guard
proves its Uzbek Cyrillic coverage. Cases that carry a GS code or a waybill
are marked ``latin_only``: transliteration would change the code.

The owner extends this file with real drafts and messages, anonymised: no
real names, card digits, phone numbers or live links. Bump CORPUS_VERSION
with every change of expected verdicts.
"""

from __future__ import annotations

from dataclasses import dataclass, field

CORPUS_VERSION = 3

# The codes «this chat's inbound messages» carry in every outbound case.
ALLOWED_TOKENS = frozenset({"GS367", "GS 367", "YW26-004715"})


@dataclass(frozen=True)
class Outbound:
    text: str
    verdict: str
    flags: frozenset[str] = field(default_factory=frozenset)
    latin_only: bool = False


@dataclass(frozen=True)
class Inbound:
    text: str
    signals: frozenset[str]
    latin_only: bool = False


def block(text: str, *flags: str, latin_only: bool = False) -> Outbound:
    return Outbound(text, "block", frozenset(flags), latin_only)


def ok(text: str, *, latin_only: bool = False) -> Outbound:
    return Outbound(text, "pass", frozenset(), latin_only)


def inbound(text: str, *signals: str, latin_only: bool = False) -> Inbound:
    return Inbound(text, frozenset(signals), latin_only)


def quiet(text: str, *, latin_only: bool = False) -> Inbound:
    return Inbound(text, frozenset(), latin_only)


